import tkinter as tk
from tkinter import ttk

# Colors
BG_MAIN = "#121214"
BG_CARD = "#1a1a1e"
TEXT_COLOR = "#e1e1e6"
TEXT_MUTED = "#8d8d99"
ACCENT_GREEN = "#10b981"
ACCENT_BLUE = "#3b82f6"
ACCENT_RED = "#ef4444"
BORDER_COLOR = "#29292e"

# Application Base64 GIF Icon (16x16 blue circle)
APP_ICON_BASE64 = """"""

FONT_SIZE = 10

def setup_styles(font_size=10, theme="Dark Mode", root=None):
    global BG_MAIN, BG_CARD, TEXT_COLOR, TEXT_MUTED, ACCENT_GREEN, ACCENT_BLUE, ACCENT_RED, BORDER_COLOR, FONT_SIZE
    FONT_SIZE = font_size
    
    if theme == "Light Mode":
        BG_MAIN = "#f4f4f5"
        BG_CARD = "#ffffff"
        TEXT_COLOR = "#18181b"
        TEXT_MUTED = "#71717a"
        ACCENT_GREEN = "#10b981"
        ACCENT_BLUE = "#2563eb"
        ACCENT_RED = "#dc2626"
        BORDER_COLOR = "#e4e4e7"
    else: # Dark Mode
        BG_MAIN = "#121214"
        BG_CARD = "#1a1a1e"
        TEXT_COLOR = "#e1e1e6"
        TEXT_MUTED = "#8d8d99"
        ACCENT_GREEN = "#10b981"
        ACCENT_BLUE = "#3b82f6"
        ACCENT_RED = "#ef4444"
        BORDER_COLOR = "#29292e"

    style = ttk.Style()
    style.theme_use("clam")
    
    font_family = "Helvetica"
    normal_font = (font_family, font_size)
    bold_font = (font_family, font_size, "bold")
    header_font = (font_family, font_size + 6, "bold")
    tab_font = (font_family, font_size - 1 if font_size > 8 else 8, "bold")
    
    # Configure overall widget properties
    style.configure(".", background=BG_MAIN, foreground=TEXT_COLOR, fieldbackground=BG_MAIN, font=normal_font)
    
    # Card style
    style.configure("Card.TFrame", background=BG_CARD, bordercolor=BORDER_COLOR, relief="solid", borderwidth=1)
    style.configure("CardLabel.TLabel", background=BG_CARD, foreground=TEXT_COLOR, font=bold_font)
    style.configure("Header.TLabel", background=BG_MAIN, foreground=ACCENT_GREEN, font=header_font)
    
    # Buttons
    style.configure("Green.TButton", background=ACCENT_GREEN, foreground="#ffffff", font=bold_font, borderwidth=0)
    style.map("Green.TButton", background=[("active", "#059669")])
    
    style.configure("Blue.TButton", background=ACCENT_BLUE, foreground="#ffffff", font=bold_font, borderwidth=0)
    style.map("Blue.TButton", background=[("active", "#1d4ed8" if theme == "Light Mode" else "#2563eb")])
    
    style.configure("Red.TButton", background=ACCENT_RED, foreground="#ffffff", font=bold_font, borderwidth=0)
    style.map("Red.TButton", background=[("active", "#b91c1c" if theme == "Light Mode" else "#dc2626")])
    
    style.configure("Gray.TButton", background="#e4e4e7" if theme == "Light Mode" else "#3e3e42", foreground=TEXT_COLOR, font=normal_font, borderwidth=1 if theme == "Light Mode" else 0, bordercolor=BORDER_COLOR)
    style.map("Gray.TButton", background=[("active", "#d4d4d8" if theme == "Light Mode" else "#4e4e54")])

    # Notebook Tab Styling
    style.configure("TNotebook", background=BG_MAIN, borderwidth=0)
    style.configure("TNotebook.Tab", background=BG_CARD, foreground=TEXT_MUTED, borderwidth=1, bordercolor=BORDER_COLOR, padding=[12, 6], font=tab_font)
    style.map("TNotebook.Tab", 
              background=[("selected", BG_MAIN), ("active", "#e4e4e7" if theme == "Light Mode" else "#222226")], 
              foreground=[("selected", TEXT_COLOR), ("active", TEXT_COLOR)],
              bordercolor=[("selected", BORDER_COLOR)],
              padding=[("selected", [12, 6]), ("active", [12, 6])])

    # Combobox Styling
    style.configure("TCombobox", 
                    background=BG_CARD, 
                    foreground=TEXT_COLOR, 
                    fieldbackground=BG_MAIN, 
                    bordercolor=BORDER_COLOR, 
                    lightcolor=BORDER_COLOR, 
                    darkcolor=BORDER_COLOR, 
                    arrowcolor=TEXT_COLOR)
    style.map("TCombobox", 
              fieldbackground=[("readonly", BG_MAIN)], 
              foreground=[("readonly", TEXT_COLOR)],
              background=[("readonly", BG_CARD), ("active", BG_CARD)])
              
    if root:
        root.option_add("*TCombobox*Listbox.background", BG_CARD)
        root.option_add("*TCombobox*Listbox.foreground", TEXT_COLOR)
        root.option_add("*TCombobox*Listbox.selectBackground", ACCENT_BLUE)
        root.option_add("*TCombobox*Listbox.selectForeground", "#ffffff")
        root.option_add("*TCombobox*Listbox.font", normal_font)

    # Label styles for metrics and cards
    style.configure("MetricVal.TLabel", background=BG_CARD, foreground=ACCENT_GREEN, font=(font_family, font_size + 4, "bold"))
    style.configure("MetricLbl.TLabel", background=BG_CARD, foreground=TEXT_MUTED, font=(font_family, font_size - 1 if font_size > 8 else 8))
    style.configure("StatusOn.TLabel", background=BG_MAIN, foreground=ACCENT_GREEN, font=bold_font)
    style.configure("StatusOff.TLabel", background=BG_MAIN, foreground=ACCENT_RED, font=bold_font)

def bind_hover(widget, hover_bg, normal_bg):
    """Binds standard mouse hover behavior to basic Tkinter widgets."""
    def on_enter(e):
        try:
            widget.config(bg=hover_bg)
        except Exception:
            pass
    def on_leave(e):
        try:
            widget.config(bg=normal_bg)
        except Exception:
            pass
    widget.bind("<Enter>", on_enter)
    widget.bind("<Leave>", on_leave)

